def style_figure(fig):
    fig.update_layout(
        paper_bgcolor="#FFFDF8",
        plot_bgcolor="#FFFDF8",
        font=dict(family="Arial, sans-serif", color="#2B1D16", size=13),
        title_font=dict(size=17, color="#2B1D16"),
        margin=dict(l=16, r=16, t=58, b=24),
        colorway=["#C8792C", "#2B1D16", "#0D9488", "#E9C982", "#A93226"],
    )
    fig.update_xaxes(gridcolor="#E9E0D4", zeroline=False)
    fig.update_yaxes(gridcolor="#E9E0D4", zeroline=False)
    return fig

def header(title, subtitle):

    st.header(title)

    st.caption(subtitle)

def filtered_frame(frame):

    result = frame.copy()

    c1, c2, c3 = st.columns(3)

    years = sorted(result["_year"].dropna().astype(int).unique().tolist()) if "_year" in result else []

    with c1:

        chosen_years = st.multiselect("Year", years, default=years, key=f"{page}_years")

    with c2:

        severities = sorted(result["severity_level"].dropna().astype(str).unique().tolist()) if "severity_level" in result else []

        chosen_severity = st.multiselect("Severity", severities, default=severities, key=f"{page}_sev")

    with c3:

        types = sorted(result["incident_type"].dropna().astype(str).unique().tolist()) if "incident_type" in result else []

        chosen_types = st.multiselect("Incident type", types, default=types, key=f"{page}_types")

    # Apply a filter only when the user has selected values.
    # An empty selection means "All" for that filter.
    if "_year" in result and chosen_years:
        result = result[result["_year"].isin(chosen_years)]
    if "severity_level" in result and chosen_severity:
        result = result[
            result["severity_level"].astype(str).isin(chosen_severity)
        ]
    if "incident_type" in result and chosen_types:
        result = result[
            result["incident_type"].astype(str).isin(chosen_types)
        ]

    return result

