    status_mid.metric("NLP dataset", f"{len(nlp_df):,} rows" if not nlp_df.empty else "Unavailable")
    status_right.metric("PostgreSQL", "Connected" if database_available else "Unavailable")

    root_model_path = ROOT / "models" / "root_cause_pipeline.joblib"
    risk_model_path = ROOT / "models" / "risk_level_pipeline.joblib"
